SELECT CASE WHEN credit_limit >= 12900 THEN 'LARGE' ELSE 'SMALL' END AS credit_limit_tier, city, segment, APPROX_PERCENTILE(age, 0.5) AS age_p50, CORR(credit_limit, age) AS corr_credit_limit_age, SUM(CASE WHEN city = 'London' THEN credit_limit ELSE 0 END) AS london_credit_limit, GROUPING(CASE WHEN credit_limit >= 12900 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM customers GROUP BY GROUPING SETS ((CASE WHEN credit_limit >= 12900 THEN 'LARGE' ELSE 'SMALL' END, city, segment), (CASE WHEN credit_limit >= 12900 THEN 'LARGE' ELSE 'SMALL' END, city), (CASE WHEN credit_limit >= 12900 THEN 'LARGE' ELSE 'SMALL' END));
